import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

interface ModeLimitsState {
  currentLimits: GeospatialLimits;
  radius: number;
  yaw: number;
  accessorsInstalled: boolean;
}

const states = new WeakMap<GeospatialCamera, ModeLimitsState>();

function getState(camera: GeospatialCamera): ModeLimitsState {
  let state = states.get(camera);
  if (!state) {
    state = {
      currentLimits: camera.limits,
      radius: camera.radius,
      yaw: camera.yaw,
      accessorsInstalled: false,
    };
    states.set(camera, state);
  }
  return state;
}

function clampRadius(value: number, limits: GeospatialLimits): number { ... }
function clampYaw(value: number, limits: GeospatialLimits): number { ... }

function applyLimits(state: ModeLimitsState, limits: GeospatialLimits): void {
  state.currentLimits = limits;
  state.radius = clampRadius(state.radius, limits);
  state.yaw = clampYaw(state.yaw, limits);
}

function installAccessors(camera: GeospatialCamera, state: ModeLimitsState): void {
  if (state.accessorsInstalled) return;
  state.accessorsInstalled = true;
  Object.defineProperty(camera, "radius", {
    configurable: true,
    enumerable: true,
    get: () => state.radius,
    set: (value: number) => {
      state.radius = clampRadius(value, state.currentLimits);
    },
  });
  Object.defineProperty(camera, "yaw", {
    configurable: true,
    enumerable: true,
    get: () => state.yaw,
    set: (value: number) => {
      state.yaw = clampYaw(value, state.currentLimits);
    },
  });
  Object.defineProperty(camera, "limits", {
    configurable: true,
    enumerable: true,
    get: () => state.currentLimits,
    set: (value: GeospatialLimits) => {
      applyLimits(state, value);
    },
  });
}

export function useModeLimits(camera: GeospatialCamera, limits: GeospatialLimits): void {
  const state = getState(camera);
  installAccessors(camera, state);
  applyLimits(state, limits);
}

