function getDescriptor(obj: object, key: string): PropertyDescriptor | undefined {
  let proto = obj;
  while (proto) {
    const desc = Object.getOwnPropertyDescriptor(proto, key);
    if (desc) return desc;
    proto = Object.getPrototypeOf(proto);
  }
  return undefined;
}

