  if (!Number.isFinite(value)) return min;
  let span = max - min;
  if (span < 0) span += TWO_PI;
  if (span >= TWO_PI - EPSILON) return value;
  if (span < EPSILON) return min;
  const offset = ((value - min) % TWO_PI + TWO_PI) % TWO_PI;
  if (offset <= span + EPSILON) {
    let candidate = min + offset;
    if (max < min && candidate > max) {
      candidate -= TWO_PI;
    }
    return candidate;
  }
  const distanceToMax = offset - span;
  const distanceToMin = TWO_PI - offset;
  const chosen = distanceToMax <= distanceToMin ? max : min;
  return chosen;
}

