    if (typeof setOrientation === "function") {
      try {
        setOrientation.call(camera, camera.yaw, camera.pitch, camera.radius, camera.center);
      } catch {
        // Ignore; limits remain enforced through the accessors.
      }
    }
  } finally {
    state.applying = false;
  }
}

