  }

  const offset = (v - min + TWO_PI) % TWO_PI;
  if (offset <= normalizedSpan + EPSILON) {
    return v;
  }

  const distanceToMax = offset - normalizedSpan;
  const distanceToMin = TWO_PI - offset;
  return distanceToMax <= distanceToMin ? max : min;
